def all_oriented(grid):
 counts=Counter(v for row in grid for v in row); color=min(v for v in counts if v)
 cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
 pts=[(r-min(a for a,b in cells),c-min(b for a,b in cells)) for r,c in cells]
 variants=set()
 for rot in range(4):
  pp=pts[:]
  for _ in range(rot): pp=[(c,-r) for r,c in pp]
  for refl in range(2):
   qq=[(r, -c if refl else c) for r,c in pp]
   mr=min(r for r,c in qq); mc=min(c for r,c in qq)
   variants.add(tuple(sorted((r-mr,c-mc) for r,c in qq)))
 out=[row[:] for row in grid]
 for sh in variants:
  hh=max(r for r,c in sh)+1; ww=max(c for r,c in sh)+1
  for r in range(len(grid)-hh+1):
   for c in range(len(grid[0])-ww+1):
    if all(grid[r+a][c+b]==0 for a,b in sh):
     for a,b in sh: out[r+a][c+b]=color
 return out
